#!/usr/bin/env python3
'''Deterministic offline check for chapter K-WORK-004.

It checks four mechanisms:
1. comparability fields and a negative control that ignores event boundary;
2. warmup path coverage and a negative control that accepts one warmed path;
3. ratio of means versus mean of per-request ratios;
4. hierarchical variance of a run mean versus flat pooling.

No project import, no file access, no network, no subprocess.
'''

from fractions import Fraction

REQUIRED = (
    'environment',
    'workload',
    'state_policy',
    'event_boundary',
    'aggregation',
    'instrumentation',
)


def validate_comparability(a, b):
    issues = []
    for key in REQUIRED:
        if key not in a or key not in b:
            issues.append('missing:' + key)
        elif a[key] != b[key]:
            issues.append('mismatch:' + key)
    return issues


def legacy_validator(a, b):
    # Intentionally incomplete: ignores event boundary and instrumentation.
    issues = []
    for key in ('environment', 'workload', 'state_policy', 'aggregation'):
        if key not in a or key not in b:
            issues.append('missing:' + key)
        elif a[key] != b[key]:
            issues.append('mismatch:' + key)
    return issues


def warmup_ready(required, warmed):
    return set(required).issubset(set(warmed))


def first_warm_only(required, warmed):
    # Intentionally faulty: one warmed path is treated as all paths.
    return len(warmed) > 0


def ratio_of_means(a, b):
    if not a or not b:
        raise ValueError('empty sample')
    return Fraction(sum(a), len(a)) / Fraction(sum(b), len(b))


def mean_of_ratios(a, b):
    if len(a) != len(b) or not a:
        raise ValueError('paired samples required')
    total = Fraction(0, 1)
    for x, y in zip(a, b):
        if y == 0:
            raise ZeroDivisionError('zero denominator')
        total += Fraction(x, y)
    return total / len(a)


def sample_variance(xs):
    n = len(xs)
    if n < 2:
        raise ValueError('need at least two values')
    mean = Fraction(sum(xs), n)
    return sum((Fraction(x) - mean) ** 2 for x in xs) / (n - 1)


def hierarchical_var_of_mean(run_means):
    r = len(run_means)
    if r < 2:
        raise ValueError('need at least two runs')
    return sample_variance(run_means) / r


def flat_var_of_mean(run_means, n_per_run):
    if n_per_run < 1:
        raise ValueError('n_per_run must be positive')
    all_values = [m for m in run_means for _ in range(n_per_run)]
    if len(all_values) < 2:
        raise ValueError('need at least two observations')
    return sample_variance(all_values) / len(all_values)


def expect_raises(fn, exc, label):
    try:
        fn()
    except exc:
        return True
    except Exception as error:
        raise AssertionError(label + ': wrong exception ' + type(error).__name__)
    raise AssertionError(label + ': no exception')


def main():
    base = {
        'environment': 'env-1',
        'workload': 'trace-1',
        'state_policy': 'cold-prefix-empty',
        'event_boundary': 'final-response',
        'aggregation': 'request-latency-mean',
        'instrumentation': 'service-timing',
    }
    same = dict(base)
    bad_boundary = dict(base)
    bad_boundary['event_boundary'] = 'first-visible-chunk'
    assert validate_comparability(base, same) == []
    boundary_issues = validate_comparability(base, bad_boundary)
    assert boundary_issues == ['mismatch:event_boundary'], boundary_issues
    legacy_issues = legacy_validator(base, bad_boundary)
    assert legacy_issues == [], legacy_issues
    print('comparability: valid=[] boundary_rejected=' + repr(boundary_issues) + ' legacy_accepts_bad=' + repr(legacy_issues == []))

    required = {'prefill-512', 'decode-1', 'decode-32'}
    assert warmup_ready(set(), set()) is True
    assert warmup_ready(required, {'prefill-512', 'decode-1'}) is False
    assert warmup_ready(required, required) is True
    assert first_warm_only(required, {'prefill-512'}) is True
    print('warmup: missing_bucket_rejected=True faulty_first_only_accepts=True')

    a = [1, 9]
    b = [2, 8]
    ratio = ratio_of_means(a, b)
    mean_ratio = mean_of_ratios(a, b)
    assert ratio == Fraction(1, 1), ratio
    assert mean_ratio == Fraction(13, 16), mean_ratio
    assert ratio != mean_ratio
    print('estimand: ratio_of_means=' + str(ratio) + ' mean_of_ratios=' + str(mean_ratio) + ' unequal=True')

    h1 = hierarchical_var_of_mean([100, 200])
    f1 = flat_var_of_mean([100, 200], 1)
    assert h1 == f1, (h1, f1)
    h1000 = hierarchical_var_of_mean([100, 200])
    f1000 = flat_var_of_mean([100, 200], 1000)
    assert f1000 < h1000, (f1000, h1000)
    assert hierarchical_var_of_mean([100, 100]) == 0
    print('hierarchy: n=1_equal=' + str(h1 == f1) + ' flat_n1000=' + str(f1000) + ' hierarchical=' + str(h1000) + ' understated=' + str(f1000 < h1000))

    expect_raises(lambda: ratio_of_means([], [1]), ValueError, 'empty numerator')
    expect_raises(lambda: mean_of_ratios([1], [0]), ZeroDivisionError, 'zero denominator')
    expect_raises(lambda: hierarchical_var_of_mean([100]), ValueError, 'single run')
    print('edge_cases: empty_sample=True zero_denominator=True single_run=True')

    print('negative_controls_detected=4')
    print('scope=CPU-only algebra and state invariants; no profiler, GPU, service or timing measurement')


if __name__ == '__main__':
    main()
